// IA-64 Specific System Call
// Copies gate page kernel unwind data
size_t BUF_SIZE = 512;
char buf[BUF_SIZE];
long needed_size;

// Returns required size (or < 0 on error)
needed_size = getunwind(buf, BUF_SIZE);

if (needed_size < 0) {
    // Handle error (e.g., ENOSYS on non-IA64)
}

// Common Error: Data is copied ONLY IF buf_size >= needed_size
if (needed_size > BUF_SIZE) {
    // Buffer too small. Data was NOT copied.
    // Retry with malloc(needed_size)
} else {
    // Data copied successfully
    // Data size is needed_size bytes
}
